    mahjong_kw("mahjong-four-players.html", "Four Players", "Mahjong four players — why American mah jongg needs exactly four.", "mahjong four players, 4 player mah jongg", "Mahjong — Four Players", "<p>American <strong>mahjong</strong> is a four-player game — one player per side of the table. Learn in <a href=\"mahjong-101.html\">Mahjong 101</a> with 4–8 guests (we rotate).</p>"),
