    mahjong_kw("weekend-mahjong-lesson.html", "Weekend Lessons", "Weekend mahjong lesson — Saturday or Sunday private class.", "weekend mahjong lesson, saturday mah jongg class", "Weekend Mahjong Lesson", "<p>Book a <strong>weekend mahjong lesson</strong> — Saturday or Sunday, 4–8 friends, we bring everything. <a href=\"mahjong-101.html\">Mahjong 101</a> $125/person.</p>", priority="0.89"),
